import type { QuizQuestion } from '../../types/quiz';

const questions: QuizQuestion[] = [
  { q: '"Mona Lisa" tablosunu kim yaptı?', a: ['Michelangelo', 'Raphael', 'Leonardo da Vinci', 'Botticelli'], c: 2, e: 'Mona Lisa, 16. yüzyılda Leonardo da Vinci tarafından yapıldı. Louvre Müzesi\'nde sergilenen tablo, dünyanın en çok ziyaret edilen eseridir.' },
  { q: 'Sistine Şapeli tavanını kim boyamıştır?', a: ['Leonardo da Vinci', 'Michelangelo', 'Raphael', 'Titian'], c: 1, e: 'Michelangelo, 1508-1512 yılları arasında sırtüstü yatarak Sistine Şapeli tavanını boyadı. "Adem\'in Yaratılışı" bu eserin en ünlü sahnesidir.' },
  { q: '"Yıldızlı Gece" tablosunu kim yaptı?', a: ['Claude Monet', 'Paul Gauguin', 'Vincent van Gogh', 'Paul Cézanne'], c: 2, e: 'Van Gogh, 1889\'da bir akıl hastanesinde tedavi görürken "Yıldızlı Gece"yi yazdı. New York MoMA\'da sergilenmektedir.' },
  { q: '"Çığlık" tablosunu kim yaptı?', a: ['Gustav Klimt', 'Edvard Munch', 'Egon Schiele', 'Paul Klee'], c: 1, e: 'Norveçli ressam Edvard Munch\'un 1893 tarihli eseri modern kaygı ve varoluş korkusunun simgesi haline gelmiştir.' },
  { q: '"Guernica" tablosunu kim yaptı?', a: ['Salvador Dali', 'Pablo Picasso', 'Joan Miró', 'Juan Gris'], c: 1, e: 'Picasso, 1937\'de İspanya İç Savaşı\'nda Guernica kasabasının bombalanmasını protesto etmek için bu tabloyu yarattı.' },
  { q: 'Van Gogh hangi ülkelidir?', a: ['Belçika', 'Fransa', 'Almanya', 'Hollanda'], c: 3, e: 'Vincent van Gogh (1853-1890) Hollandalıdır. Yaşarken sadece bir tablo satabilen Van Gogh, bugün tarihin en pahalı sanatçıları arasındadır.' },
  { q: 'Empresyonizm akımı hangi ülkede başladı?', a: ['İtalya', 'Almanya', 'Fransa', 'İngiltere'], c: 2, e: 'Empresyonizm 1860\'larda Fransa\'da Monet, Renoir ve Degas öncülüğünde başladı. "İzlenim" anlamındaki Fransızca "impression"dan adını alır.' },
  { q: 'Türk resim sanatının öncüsü sayılan ressam kimdir?', a: ['Osman Hamdi Bey', 'İbrahim Çallı', 'Halil Paşa', 'Şeker Ahmet Paşa'], c: 0, e: 'Osman Hamdi Bey (1842-1910) hem ressam hem müze kurucusudur. İstanbul Arkeoloji Müzesi\'ni kurmuş, Türk müzeciliğinin öncüsüdür.' },
  { q: '"Kaplumbağa Terbiyecisi" tablosunun ressamı kimdir?', a: ['İbrahim Çallı', 'Osman Hamdi Bey', 'Şeker Ahmet Paşa', 'Avni Lifij'], c: 1, e: 'Osman Hamdi Bey\'in 1906 tarihli bu eseri, Türk resminin en çok tanınan tablolarından biridir. Şu an Pera Müzesi\'ndedir.' },
  { q: 'Beethoven kaç numaralı senfonisini sağır olarak besteledi?', a: ['5. Senfoni', '7. Senfoni', '9. Senfoni', '6. Senfoni'], c: 2, e: 'Beethoven 9. Senfoni\'yi 1824\'te tamamen sağırken besteledi. Eserin prömiyerinde Beethoven müziği duymamış, seyircinin alkışladığını fark etmemiştir.' },
  { q: 'Mozart hangi yaşta hayatını kaybetti?', a: ['25', '30', '35', '40'], c: 2, e: 'Wolfgang Amadeus Mozart, 5 Aralık 1791\'de 35 yaşında hayatını kaybetti. 6 yaşından itibaren beste yapan Mozart, 600\'den fazla eser bıraktı.' },
  { q: '"Dört Mevsim" eserini kim besteledi?', a: ['Bach', 'Handel', 'Vivaldi', 'Haydn'], c: 2, e: 'Antonio Vivaldi\'nin 1723\'te bestelediği "Dört Mevsim", keman konçertolarından oluşan ve programlı müziğin erken örneklerinden biridir.' },
  { q: 'Shakespeare hangi ülkelidir?', a: ['Fransa', 'Almanya', 'İtalya', 'İngiltere'], c: 3, e: 'William Shakespeare (1564-1616), Stratford-upon-Avon\'da doğdu. 37 oyun ve 154 sonet yazan Shakespeare, İngiliz edebiyatının zirvesidir.' },
  { q: '"Don Kişot" romanını kim yazdı?', a: ['Shakespeare', 'Dante', 'Cervantes', 'Goethe'], c: 2, e: 'Miguel de Cervantes\'in 1605\'te yazdığı Don Kişot, modern romanın başlangıcı sayılır. "Dünyanın ilk romanı" olarak da anılır.' },
  { q: '"Suç ve Ceza" romanını kim yazdı?', a: ['Leo Tolstoy', 'Anton Chekhov', 'Ivan Turgenev', 'Fyodor Dostoyevski'], c: 3, e: 'Dostoyevski\'nin 1866\'da yazdığı "Suç ve Ceza", bir cinayetin psikolojik ağırlığını işler; psikolojik romanın şaheseri sayılır.' },
  { q: '"Savaş ve Barış" romanını kim yazdı?', a: ['Dostoyevski', 'Turgenev', 'Leo Tolstoy', 'Gorki'], c: 2, e: 'Tolstoy\'un 1869\'da tamamladığı bu devasa roman, Napolyon savaşları döneminde Rus aristokrasisini konu alır; edebiyatın zirvelerinden biridir.' },
  { q: 'Türk edebiyatının ilk romanı sayılan eser hangisidir?', a: ['İntibah', 'Araba Sevdası', 'Taaşşuk-ı Talat ve Fitnat', 'Zehra'], c: 2, e: '"Taaşşuk-ı Talat ve Fitnat" (1872), Şemseddin Sami tarafından yazılan Türk edebiyatının ilk romanı kabul edilir.' },
  { q: '"İnce Memed" romanının yazarı kimdir?', a: ['Ahmet Hamdi Tanpınar', 'Sabahattin Ali', 'Yaşar Kemal', 'Orhan Pamuk'], c: 2, e: 'Yaşar Kemal\'in 1955\'te yazdığı "İnce Memed", Çukurova\'da geçen ve ağa baskısına karşı mücadeleyi anlatan başyapıttır.' },
  { q: 'Türkiye\'den Nobel Edebiyat Ödülü alan tek isim kimdir?', a: ['Yaşar Kemal', 'Orhan Pamuk', 'Murathan Mungan', 'Zülfü Livaneli'], c: 1, e: 'Orhan Pamuk, 2006\'da Nobel Edebiyat Ödülü kazandı. "Kar", "Benim Adım Kırmızı" ve "İstanbul" en tanınan eserleri arasındadır.' },
  { q: '"1984" distopik romanını kim yazdı?', a: ['Aldous Huxley', 'George Orwell', 'Ray Bradbury', 'Franz Kafka'], c: 1, e: 'George Orwell\'ın 1949\'da yazdığı "1984", totaliter bir devleti anlatan distopik bir başyapıttır. "Büyük Birader" kavramı bu kitaptan gelir.' },
  { q: 'Pop Art akımının öncüsü sayılan sanatçı kimdir?', a: ['Jackson Pollock', 'Mark Rothko', 'Andy Warhol', 'Roy Lichtenstein'], c: 2, e: 'Andy Warhol, 1960\'larda Campbell\'s çorba kutularını ve Marilyn Monroe portresini sanata dönüştürerek Pop Art\'ı tanımladı.' },
  { q: '"Düşünür" heykelinin sanatçısı kimdir?', a: ['Michelangelo', 'Donatello', 'Auguste Rodin', 'Bernini'], c: 2, e: 'Fransız heykeltıraş Auguste Rodin\'in 1880\'de yaptığı "Düşünür" (Le Penseur), felsefî düşüncenin evrensel simgesi haline gelmiştir.' },
  { q: 'Divan edebiyatının en büyük şairi kabul edilen isim kimdir?', a: ['Baki', 'Fuzuli', 'Nedim', 'Şeyh Galip'], c: 1, e: 'Fuzuli (1494-1556), hem Türkçe hem Arapça hem de Farsça yazan evrensel bir şairdir. "Leyla ve Mecnun" mesnevisi en ünlü eseridir.' },
  { q: 'Louvre Müzesi hangi şehirdedir?', a: ['Londra', 'Berlin', 'Paris', 'Amsterdam'], c: 2, e: 'Louvre, Paris\'te bulunan dünyanın en büyük ve en çok ziyaret edilen sanat müzesidir. Yaklaşık 35.000 eser barındırır.' },
  { q: '"Ay Işığı Sonatı" kimin eseridir?', a: ['Mozart', 'Chopin', 'Beethoven', 'Bach'], c: 2, e: 'Beethoven\'ın 1801\'de bestelediği bu piyano sonatı, "Ay Işığı" adını bestecinin ölümünden sonra aldı.' },
  // ── Ek Sanat & Edebiyat Soruları ─────────────────────────────────
  { q: '"Hamlet" kimin eseridir?', a: ['Marlowe', 'Molière', 'Shakespeare', 'Goethe'], c: 2, e: '"Hamlet" Shakespeare\'in en ünlü trajedisidir. "Olmak ya da olmamak, işte bütün mesele!" repliği buradan gelir.' },
  { q: 'Türk tiyatrosunun kurucusu sayılan isim kimdir?', a: ['Muhsin Ertuğrul', 'Haldun Taner', 'Aziz Nesin', 'Reşit Galip'], c: 0, e: 'Muhsin Ertuğrul, modern Türk tiyatrosunu kurdu ve yönetmenliğini yaptı; Türk sinemasının da öncüsüdür.' },
  { q: '"Faust" adlı eserin yazarı kimdir?', a: ['Schiller', 'Kafka', 'Goethe', 'Nietzsche'], c: 2, e: 'Goethe\'nin "Faust" eseri şeytanla anlaşan bir bilgini anlatır; Alman edebiyatının zirvesi kabul edilir.' },
  { q: 'Kübizm akımını kim kurdu?', a: ['Dali', 'Picasso ve Braque', 'Matisse', 'Léger'], c: 1, e: 'Pablo Picasso ve Georges Braque, 1908\'de Kübizmi geliştirdi; nesneler birden fazla bakış açısından aynı anda gösterilir.' },
  { q: 'Sürrealizm akımının öncüsü kimdir?', a: ['Salvador Dali', 'André Breton', 'Max Ernst', 'René Magritte'], c: 1, e: 'André Breton, 1924\'te "Sürrealizm Manifestosu"nu yazdı. Salvador Dali ise en tanınan sürrealist ressam oldu.' },
  { q: '"Eriyen Saatler" tablosunu kim yaptı?', a: ['Picasso', 'Magritte', 'Salvador Dali', 'Munch'], c: 2, e: 'Salvador Dali\'nin 1931 tarihli "Belleğin Azmi" (Eriyen Saatler) tablosu, zamanın göreceliliğini simgeleyen sürrealist başyapıttır.' },
  { q: '"Karamazov Kardeşler" romanının yazarı kimdir?', a: ['Tolstoy', 'Dostoyevski', 'Turgenev', 'Gogol'], c: 1, e: 'Dostoyevski\'nin 1880\'de tamamladığı son romanı; inanç, ahlak ve özgür irade temalarını işler.' },
  { q: '"Yabancı" (L\'Étranger) romanının yazarı kimdir?', a: ['Sartre', 'Camus', 'Beauvoir', 'Flaubert'], c: 1, e: 'Albert Camus\'nun 1942\'deki eseri absürdizmin simgesidir; başkahramanın annesinin ölümüne kayıtsız kalmasıyla başlar.' },
  { q: 'Türk edebiyatında Tanzimat dönemi hangi yılda başladı?', a: ['1839', '1856', '1876', '1908'], c: 0, e: 'Tanzimat Fermanı 1839\'da ilan edildi; bu dönemde Batılı edebi türler Türk edebiyatına girdi.' },
  { q: '"Servet-i Fünun" edebiyat akımının öncüsü kimdir?', a: ['Namık Kemal', 'Tevfik Fikret', 'Ziya Gökalp', 'Ahmet Haşim'], c: 1, e: 'Tevfik Fikret, Servet-i Fünun dergisini yöneterek bu akımın öncüsü oldu (1896-1901).' },
  { q: 'Türk resim tarihinde "1914 Kuşağı" neyi ifade eder?', a: ['Savaş ressamları', 'Avrupa\'da eğitim gören Türk ressamlar', 'Empresyonist grup', 'Kübist Türk sanatçılar'], c: 1, e: '1914 Kuşağı; Paris\'te eğitim alarak Türk resmini modernize eden İbrahim Çallı, Halil Paşa gibi ressamlardır.' },
  { q: '"Anna Karenina" romanının yazarı kimdir?', a: ['Dostoyevski', 'Çehov', 'Tolstoy', 'Turgenev'], c: 2, e: 'Tolstoy\'un 1877\'de tamamladığı roman; evlilik dışı aşkın trajedisini anlatır.' },
  { q: 'Türkiye\'nin en köklü tiyatrosu hangisidir?', a: ['İstanbul Şehir Tiyatroları', 'Devlet Tiyatroları', 'Ankara Sanat Tiyatrosu', 'Kenter Tiyatrosu'], c: 1, e: 'Devlet Tiyatroları, 1949\'da kuruldu; Ankara merkezli Türkiye\'nin en köklü ve yaygın tiyatro kurumudur.' },
  { q: '"Picasso\'nun Gernika\'sı" hangi tarihsel olayı anlatır?', a: ['I. Dünya Savaşı', 'İspanya İç Savaşı\'nda Guernica kasabasının bombalanması', 'II. Dünya Savaşı', 'Fransız Devrimi'], c: 1, e: '1937\'de Nazi Almanyası\'nın İspanya\'daki Guernica kasabasını bombalamasını protesto eden eserdir.' },
  { q: '"Hamlet"te ünlü monolog hangi soruyla başlar?', a: ['"Neden?"', '"Kim?"', '"Olmak ya da olmamak"', '"Nereye?"'], c: 2, e: '"To be, or not to be, that is the question" — varoluşu ve ölümü sorgulayan bu replik edebiyat tarihinin en ünlüsüdür.' },
  { q: 'Türk müziğinde "makam" nedir?', a: ['Bir enstrüman', 'Belirli ses aralıklarından oluşan dizilim ve kural sistemi', 'Bir ritim kalıbı', 'Şarkı sözü biçimi'], c: 1, e: 'Makam; melodinin hareket ettiği ses dizisini, başlangıç ve bitiş notalarını, seyre ilişkin kuralları belirler.' },
  { q: 'Aşık Veysel hangi sanatla uğraşmıştır?', a: ['Resim', 'Heykel', 'Halk şairliği (saz şairliği)', 'Tiyatro'], c: 2, e: 'Aşık Veysel Şatıroğlu, görme engelli Türk halk ozanıdır; "Uzun İnce Bir Yoldayım" onun en sevilen eseri.' },
  { q: 'Balıkesirli Türk ressam Atatürk portrelerini yapmasıyla tanınan kimdir?', a: ['İbrahim Çallı', 'Halil Paşa', 'Avni Lifij', 'Sabiha Bozcalı'], c: 3, e: 'Sabiha Bozcalı, Atatürk\'ün resmi portresini yapmış Türk kadın ressamıdır.' },
  { q: 'Türk sinemasında "Yeşilçam" adı nereden gelir?', a: ['Bir yapımcı adı', 'İstanbul\'da bir sokak adı', 'İlk stüdyonun adı', 'Film türü'], c: 1, e: 'Yeşilçam, İstanbul Beyoğlu\'ndaki Yeşilçam Sokağı\'ndan adını alır; yapım şirketleri burada yoğunlaşmıştı.' },
  { q: '"Halide Edip Adıvar"ın en ünlü romanı hangisidir?', a: ['Sinekli Bakkal', 'İnce Memed', 'Çalıkuşu', 'Vurun Kahpeye'], c: 0, e: '"Sinekli Bakkal" (1935), İstanbul\'un geleneksel mahalle yaşamını anlatan, ilk İngilizce çevirileri yapılan Türk romanlarından.' },
  { q: 'Reşat Nuri Güntekin\'in en ünlü eseri hangisidir?', a: ['İnce Memed', 'Çalıkuşu', 'Sinekli Bakkal', 'Yaprak Dökümü'], c: 1, e: '"Çalıkuşu" (1922), idealist öğretmen Feride\'nin Anadolu\'daki maceralarını anlatan klasik Türk romanıdır.' },
  { q: 'Orhan Kemal\'in eserlerinin konusu ağırlıklı olarak nedir?', a: ['Osmanlı tarihi', 'İşçi sınıfı ve yoksullar', 'Aşk hikayeleri', 'Felsefi düşünceler'], c: 1, e: 'Orhan Kemal, Adana pamuk tarlası işçilerini ve fabrika emekçilerini anlatan toplumcu gerçekçi bir yazardır.' },
  { q: '"Bir Gün Tek Başınasın" kimin şiirine aittir?', a: ['Nazım Hikmet', 'Orhan Veli', 'Cemal Süreya', 'Edip Cansever'], c: 1, e: 'Orhan Veli Kanık, geleneksel divan şiiri kalıplarını kırarak sade ve halk diline yakın şiirleriyle Türk şiirini dönüştürdü.' },
  { q: 'Aziz Nesin\'in eserlerinin temel özelliği nedir?', a: ['Romantik aşk', 'Toplumsal hiciv ve yergi', 'Tarihi anlatı', 'Felsefi monologlar'], c: 1, e: 'Aziz Nesin, bürokratik ve sosyal çarpıklıkları mizah ve hicivle eleştiren Türk edebiyatının en önemli yazarlarından.' },
  { q: '"Şiir nedir?" sorusuna "sözcüklerin müziği" diyen Fransız şair kimdir?', a: ['Rimbaud', 'Baudelaire', 'Verlaine', 'Mallarmé'], c: 2, e: 'Paul Verlaine "Şiir Sanatı"nda şiiri müzikle özdeşleştirdi; sembolizm akımının öncülerindendir.' },
  // ── Ek Sanat Soruları ─────────────────────────────────────────────
  { q: 'Türk heykel sanatının öncüsü sayılan sanatçı kimdir?', a: ['Zühtü Müridoğlu', 'Hüseyin Gezer', 'Ali Hadi Bara', 'Nusret Suman'], c: 2, e: 'Ali Hadi Bara (1906-1971), Türkiye\'nin ilk uluslararası tanınırlık kazanan heykeltraşıdır; figüratif heykelleriyle öne çıkmıştır.' },
  { q: '"Primitivizm" sanat akımı neyi simgeler?', a: ['Batı sanatını taklit etme', 'İlkel ve geleneksel kültürlerden ilham alma', 'Sanayileşmeyi kutlama', 'Soyut biçimleri reddeme'], c: 1, e: 'Primitivizm; Picasso ve Gauguin gibi Avrupalı sanatçıların Afrika, Okyanusya ve Asya sanatından ilham almasıyla ortaya çıktı.' },
  { q: 'Edebiyatta "akış of bilinç" (stream of consciousness) tekniğini en ünlü kullanan yazar kimdir?', a: ['Ernest Hemingway', 'James Joyce', 'F. Scott Fitzgerald', 'William Faulkner'], c: 1, e: 'James Joyce, "Ulysses" ve "Bir Genç Adamın Portresi"nde iç monolog ve bilinç akışı tekniğini zirveye taşıdı.' },
  { q: '"Mavi Dönem" hangi sanatçıyla özdeşleşmiştir?', a: ['Matisse', 'Monet', 'Picasso', 'Van Gogh'], c: 2, e: 'Picasso\'nun 1901-1904 yıllarını kapsayan Mavi Döneminde tablolara hâkim renk mavidir; yoksulluk ve hüznü yansıtır.' },
  { q: 'Türk mimarisinde "Sinan" lakabıyla anılan büyük mimar kimdir?', a: ['Davut Ağa', 'Mimar Kemalettin', 'Mimar Sinan', 'Hayreddin'], c: 2, e: 'Mimar Sinan (1490-1588), Süleymaniye ve Selimiye camilerini tasarlayan Osmanlı\'nın baş mimarıdır; 300\'den fazla eser bırakmıştır.' },
  { q: 'Selimiye Camii hangi şehirdedir?', a: ['İstanbul', 'Bursa', 'Edirne', 'Konya'], c: 2, e: 'Mimar Sinan\'ın en büyük eseri saydığı Selimiye Camii, Edirne\'de 1575\'te tamamlandı ve UNESCO listesindedir.' },
  { q: '"Empresyonizm" akımının ismi nereden gelir?', a: ['Bir sanatçının adından', 'Monet\'nin "İzlenim, Gün Doğumu" adlı tablosundan', 'Fransız bir dergiden', 'Bir sergi adından'], c: 1, e: '1874\'te eleştirmen Louis Leroy, Monet\'nin "Impression, Soleil Levant" tablosunu alay yollu "empresyonist" diye adlandırdı; isim kaldı.' },
  { q: 'Türkiye\'de "devlet sanatçısı" unvanı kime verilir?', a: ['Herkese', 'Sanat alanında üstün başarı gösteren kişilere devlet tarafından', 'Yabancı sanatçılara', 'Emekli sanatkarlara'], c: 1, e: 'Devlet Sanatçısı unvanı, Kültür Bakanlığı\'nın kararıyla sanat alanında olağanüstü katkı sağlayan kişilere verilir.' },
  { q: '"Gotik" mimari stili hangi öğelerle tanınır?', a: ['Düz çatılar ve simetri', 'Sivri kemerler, uçan payandalar ve yüksek kuleler', 'Sütunlar ve kubbeler', 'Tahta çerçeveler'], c: 1, e: 'Gotik mimari 12-16. yüzyıl Avrupa\'sında doğdu; ışığı içeri almak için büyük vitray pencereler ve sivri kemerler kullanıldı.' },
  { q: '"Barok" sanat döneminin temel özelliği nedir?', a: ['Sadelik ve minimalizm', 'Abartılı süsleme, dramatik ışık-gölge ve hareket duygusu', 'Geometrik soyutlama', 'Doğadan uzaklaşma'], c: 1, e: 'Barok sanat (17. yüzyıl); dramatik ışık kontrastı (chiaroscuro), dinamizm ve görkemli süslemeyle tanınır. Caravaggio ve Rubens öncülerindendir.' },
  { q: '"Kolaj" tekniği nedir?', a: ['Kağıt üzerine çizim', 'Farklı malzemelerin yapıştırılmasıyla oluşturulan sanat', 'Boyama tekniği', 'Heykel yöntemi'], c: 1, e: 'Kolaj; gazete kesiği, kumaş parçası gibi malzemelerin bir yüzeye yapıştırılmasıyla oluşturulan eserdir. Picasso ve Braque öncüdür.' },
  { q: '"Türk ebru sanatı" ne üzerine yapılır?', a: ['Kağıt', 'Su yüzeyine boyalar yayılarak kağıda aktarılır', 'Ahşap', 'Deri'], c: 1, e: 'Ebru; suyun yüzeyine damlanan boyaların çeşitli araçlarla şekillendirilip kağıda aktarılmasıyla oluşan geleneksel Türk sanatıdır.' },
  { q: 'Ahmet Hamdi Tanpınar hangi edebî akımla özdeşleşir?', a: ['Servet-i Fünun', 'Toplumcu Gerçekçilik', 'Modernizm ve psikolojik roman', 'Millî Edebiyat'], c: 2, e: 'Tanpınar, Doğu-Batı sentezi, zaman, bilinçaltı ve Türk kimliğini işleyen modernist bir yazardır; "Saatleri Ayarlama Enstitüsü" başyapıtıdır.' },
  { q: '"Sabahattin Ali" hangi nedenden dolayı önemlidir?', a: ['İlk Türk romancı', 'Toplumsal gerçekçi hikaye ve romanlarıyla', 'İlk kadın yazar', 'Divan şairi'], c: 1, e: 'Sabahattin Ali (1907-1948), Anadolu insanının hayatını anlatan toplumcu gerçekçi eserleriyle tanınır; "Kürk Mantolu Madonna" en ünlüsüdür.' },
  { q: '"Minyatür" sanatı Türk-İslam sanatında ne anlama gelir?', a: ['Küçük heykel', 'El yazması kitaplara yapılan renkli küçük boyutlu resimler', 'Taş oyma', 'Cam işlemesi'], c: 1, e: 'Minyatür; özellikle el yazması kitaplara yapılan ayrıntılı küçük boyutlu resimlerdir. Osmanlı minyatürü İslam sanatının zirvelerindendir.' },
  { q: 'Türkiye\'de "Galeri" ile "Müze" arasındaki fark nedir?', a: ['İkisi aynıdır', 'Galeride eserler satışa sunulur, müzede kalıcı sergi', 'Galeri devlet kurumu, müze özel', 'Müzede yalnızca antikalar bulunur'], c: 1, e: 'Galeri ticari amaçlı sanat eseri sergisi-satışı yapar; müze ise eserleri koruyup kalıcı olarak toplumla buluşturur.' },
  { q: '"Op Art" (Optik Sanat) nedir?', a: ['Fotoğrafik sanat', 'Göz yanılması yaratacak geometrik desenler kullanan sanat akımı', 'Doğa resimleri', 'Video sanatı'], c: 1, e: 'Op Art 1960\'larda ortaya çıktı; geometrik şekil ve renk zıtlıklarıyla optik yanılmalar yaratmayı amaçlar. Victor Vasarely öncüsüdür.' },

  // ── YENİ SORULAR ──────────────────────────────────────────────────
  { q: '"Rönesans" sanatının merkezi hangi şehirdir?', a: ['Roma', 'Paris', 'Floransa', 'Venedik'], c: 2, e: 'Floransa, 15. yüzyılda Medici ailesi\'nin himayesiyle Rönesans\'ın kalbi oldu; Da Vinci, Botticelli ve Michelangelo burada yetişti.', d: 1 },
  { q: 'Michelangelo\'nun Sistine Şapeli\'nin tavanına yaptığı eserin adı nedir?', a: ['Yaratılış', 'Son Yargı', 'Adem\'in Yaratılışı içeren Yaratılış freski', 'Meryem Ana'], c: 2, e: 'Sistine tavanının en ünlü bölümü "Adem\'in Yaratılışı"dır; 1508-1512 arasında boyanan bu dev freski, insanlık tarihinin ikonik sanat eserleri arasındadır.', d: 1 },
  { q: '"Mona Lisa" tablosunu kim yazmıştır?', a: ['Michelangelo', 'Raphael', 'Leonardo da Vinci', 'Titian'], c: 2, e: 'Mona Lisa, Leonardo da Vinci tarafından 1503-1519 yılları arasında yapıldı; şu an Paris Louvre Müzesi\'nde sergilenmektedir.', d: 1 },
  { q: '"Van Gogh"un "Yıldızlı Gece" tablosu nerede sergilenmektedir?', a: ['Louvre, Paris', 'MoMA, New York', 'Prado, Madrid', 'Tate Modern, Londra'], c: 1, e: 'Yıldızlı Gece (1889), New York\'taki Modern Sanat Müzesi\'nde (MoMA) sergilenmektedir.', d: 2 },
  { q: '"Empresyonizm" akımı hangi ülkede ortaya çıktı?', a: ['İtalya', 'İspanya', 'Fransa', 'Almanya'], c: 2, e: 'Empresyonizm, 19. yüzyılda Fransa\'da gelişti; Monet, Renoir ve Degas bu akımın öncü isimleridir.', d: 1 },
  { q: 'Pablo Picasso hangi sanat akımının kurucusudur?', a: ['Sürrealizm', 'Kübizm', 'Fütürizm', 'Dadaizm'], c: 1, e: 'Pablo Picasso ve Georges Braque, 1900\'lerin başında Kübizm\'i kurdu; nesneleri birden fazla açıdan aynı anda gösteren devrimci bir yaklaşımdır.', d: 1 },
  { q: '"Salvador Dali" hangi sanat akımıyla tanınır?', a: ['Kübizm', 'Realizm', 'Sürrealizm', 'Ekspresyonizm'], c: 2, e: 'Salvador Dali, bilinçaltı imgelerini rüya gibi sahnelerde işleyen Sürrealizm\'in en ünlü temsilcisidir; "Belleğin Azmi" eseri ikonikleşmiştir.', d: 1 },
  { q: '"Gotik mimari"nin en belirgin özelliği nedir?', a: ['Düz çatılar ve yuvarlak kemerler', 'Sivri kemerler, uçan payandalar ve büyük vitraylar', 'Sütun sıraları ve açık avlular', 'Piramit biçimli çatılar'], c: 1, e: 'Gotik mimari (12-15. yüzyıl); sivri kemer, uçan payanda ve büyük vitray pencerelerle tanınır. Notre-Dame Katedrali en iyi örneklerden biridir.', d: 2 },
  { q: '"Empresyonist" resimde en önemli unsur nedir?', a: ['Fotoğraf gerçekliği', 'Anlık ışık ve renk etkisini yakalamak', 'Mitolojik sahneler', 'Siyasi mesajlar'], c: 1, e: 'Empresyonistler akademik kurallara uymak yerine gün ışığının anlık etkisini, canlı fırça darbeleriyle tuvale aktarmayı amaçladı.', d: 2 },
  { q: 'Türk hat sanatının en önemli malzemesi nedir?', a: ['Tuval ve yağlı boya', 'Kamış kalem, mürekkep ve kağıt/deri', 'Mermer ve kalem', 'İplik ve iğne'], c: 1, e: 'Hat sanatında kamış kalem (divit), özel mürekkep (is ya da arap zamkı bazlı) ve pişirilmiş deri ya da kağıt kullanılır.', d: 2 },
  { q: '"Pitoresk" (Picturesque) kavramı sanatta ne anlama gelir?', a: ['Geometrik mükemmellik', 'Resme uygun doğal ya da kırsal güzellik', 'Modern kent yaşamı', 'Soyut renkler'], c: 1, e: 'Pitoresk, 18. yüzyılda İngiltere\'de gelişen; düzensiz, doğal ve kırsal manzaraların estetik değerini ön plana çıkaran bir güzellik anlayışıdır.', d: 3 },
  { q: '"Fresk" tekniği nedir?', a: ['Tuval üzerine yağlı boya', 'Islak sıva üzerine su bazlı boya', 'Tahta üzerine altın varak', 'Kağıt üzerine suluboya'], c: 1, e: 'Fresk, henüz ıslak olan duvar sıvasına su bazlı pigment uygulanarak yapılan duvar resmidir; boya sıvaya işler ve kalıcı olur.', d: 2 },
  { q: 'Türk İslam sanatında geometrik desenler neden kullanılır?', a: ['Pratik sebeplerle', 'İslam\'da canlı figür yasağına karşı alternatif estetik ifade', 'Ucuz malzeme olduğu için', 'Roma mimarisini taklit etmek için'], c: 1, e: 'İslam sanatında canlı figür tasvirine getirilen kısıtlamalar nedeniyle sanatçılar geometrik desenler, arabesk ve kaligrafide ustalık geliştirdi.', d: 2 },
  { q: '"Empresyonizm" adı nereden gelir?', a: ['Bir sanat gazetesinden', 'Monet\'nin "İzlenim: Gün Doğumu" tablosundan eleştirmenlerin türettiği alay yüklü ifadeden', 'Fransız Akademisi\'nden', 'Bir sergi adından'], c: 1, e: '1874\'te bir eleştirmen, Monet\'nin "Impression, Soleil Levant" tablosuna atfen bu akımı aşağılamak için "empresyonist" dedi; ad kaldı.', d: 3 },
  { q: '"Bauhaus" hangi alanda çığır açtı?', a: ['Yalnızca resimde', 'Tasarım, mimarlık ve zanaatı birleştiren modern eğitim anlayışında', 'Yalnızca heykelde', 'Fotoğrafçılıkta'], c: 1, e: 'Bauhaus (1919-1933, Almanya), sanat ve endüstriyel tasarımı birleştiren, işlevselliği esas alan devrimci bir okul ve akım oldu.', d: 3 },
  { q: '"Soyut Ekspresyonizm" hangi ülkede gelişti?', a: ['Fransa', 'İtalya', 'Almanya', 'ABD'], c: 3, e: 'Soyut Ekspresyonizm, II. Dünya Savaşı sonrası 1940-50\'lerde New York\'ta gelişti; Jackson Pollock ve Mark Rothko öncülerindendir.', d: 3 },
  { q: 'Wolfgang Amadeus Mozart hangi ülkede doğmuştur?', a: ['Almanya', 'Avusturya', 'İtalya', 'Çekya'], c: 1, e: 'Mozart (1756-1791), Salzburg\'da (o dönem Kutsal Roma İmparatorluğu\'na bağlı) doğdu; bugün Avusturya sınırlarında kalır.', d: 1 },
  { q: 'Beethoven\'ın 9. Senfonisi hangi özelliğiyle dikkat çeker?', a: ['Tamamen piyano için yazılması', 'Sır içermesi', 'Sağır olduğu dönemde besteleyen tek senfonisti', 'Yalnızca 10 dakika sürmesi'], c: 2, e: 'Beethoven, 9. Senfoniyi neredeyse tamamen işitmez durumdayken besteledi; "Neşeye Övgü" korosu içeren finaliyle tarihsel bir başyapıttır.', d: 2 },
  { q: '"Opera"nın doğduğu ülke hangisidir?', a: ['Almanya', 'Fransa', 'İtalya', 'Avusturya'], c: 2, e: 'Opera, 16. yüzyıl sonu – 17. yüzyıl başında Floransa\'da (İtalya) Camerata topluluğunun antik Yunan dramasını yeniden canlandırma çabasıyla doğdu.', d: 2 },
  { q: '"Divan edebiyatında "kaside" nedir?', a: ['Aşk şiiri', 'Padişah veya yüksek kişilere sunulan övgü şiiri', 'Ağıt', 'Halk türküsü'], c: 1, e: 'Kaside, Divan edebiyatında padişah, vezir gibi ileri gelenlere sunulan övgü şiiridir; en az 33, genellikle 99 beyitten oluşur.', d: 2 },
  { q: '"Sürrealizm"in öncüsü ve manifestosunu yazan kişi kimdir?', a: ['Salvador Dali', 'André Breton', 'Max Ernst', 'René Magritte'], c: 1, e: 'André Breton, 1924\'te Sürrealizm Manifestosu\'nu yayımlayarak bu akımı tanımladı; bilinçaltı imgeler ve rüya sahnelerine dayanan sanatı savundu.', d: 3 },
  { q: 'Türk çini sanatının merkezi olarak bilinen şehir hangisidir?', a: ['İstanbul', 'Bursa', 'İznik', 'Konya'], c: 2, e: 'İznik çini ve seramiği, Osmanlı\'nın 15-17. yüzyıllarında zirveye ulaştı; kobalt mavisi ve kırmızı tonlarıyla dünya çapında tanınır.', d: 2 },
  { q: '"Realizm" sanat akımının öncüsü olarak kabul edilen Fransız ressam kimdir?', a: ['Gustave Courbet', 'Eugène Delacroix', 'Jacques-Louis David', 'Jean-Auguste-Dominique Ingres'], c: 0, e: 'Gustave Courbet (1819-1877), idealize etmeden sıradan insanların yaşamını tuvale taşıyarak Realizm\'in öncüsü oldu.', d: 3 },
  { q: '"Kaligrafi" (Hat) hangi alfabelerde sanat olarak gelişmiştir?', a: ['Yalnızca Arap alfabesinde', 'Arap, Çin, Japon ve Latin alfabelerinde', 'Yalnızca Latin alfabesinde', 'Yalnızca Japonca\'da'], c: 1, e: 'Hat sanatı başta Arap, Farsça ve Osmanlıca olmak üzere Çin, Japon ve belirli ölçüde Latin alfabelerinde yüksek estetik değer kazanmıştır.', d: 2 },
  { q: '"Pop Art" akımının en ünlü temsilcisi kimdir?', a: ['Andy Warhol', 'Roy Lichtenstein', 'Jasper Johns', 'Robert Rauschenberg'], c: 0, e: 'Andy Warhol, Campbell\'s çorba kutusu ve Marilyn Monroe gibi popüler kültür imgelerini sanata taşıyarak Pop Art\'ın simgesi oldu.', d: 2 },
  { q: '"Rönesans"ın Türkçe anlamı nedir?', a: ['Aydınlanma', 'Yeniden Doğuş', 'Modernizm', 'İlerleme'], c: 1, e: 'Rönesans (Renaissance), Fransızca "yeniden doğuş" demektir; antik Yunan-Roma uygarlığının değerleri ve sanatının yeniden keşfedildiği dönemi anlatır.', d: 1 },
  { q: '"Çini" ile "seramik" arasındaki fark nedir?', a: ['İkisi aynıdır', 'Çini sırlı ve dekoratif kil levhalar; seramik daha genel bir kavram', 'Seramik renkli, çini tek renkli', 'Çini metal içerir'], c: 1, e: 'Seramik pişirilmiş kil ürünlerinin genel adıdır; çini ise sırlı ve genellikle geometrik-bitkisel motiflerle bezenmiş dekoratif seramik levhalardır.', d: 2 },
  { q: '"Sürrealiz"min öncüsü André Breton hangi alanda ün kazandı?', a: ['Ressam', 'Şair ve yazar; Sürrealizm manifestosunu kaleme aldı', 'Heykeltıraş', 'Mimar'], c: 1, e: 'André Breton, 1924\'te Sürrealizm manifestosunu yayımlayan Fransız şair ve yazardır; bilinçdışı yaratıcılığı ön plana çıkaran bu akımı teorize etmesiyle tanınır.', d: 2 },
  { q: '"Claude Monet" hangi sanat akımının temsilcisidir?', a: ['Kübizm', 'Empresyonizm', 'Sürrealizm', 'Realizm'], c: 1, e: 'Claude Monet, 1870\'lerden itibaren anlık ışığı ve rengi tuvale aktaran Empresyonizm\'in önde gelen temsilcisidir; Nilüfer serisi en ünlü yapıtları arasındadır.', d: 1 },
  { q: '"Vincent van Gogh"un "Yıldızlı Gece" tablosundaki girdap sarmallar neyi simgeler?', a: ['Fırtına', 'Hareketin ve enerji akışının görsel ifadesi', 'Yıldızlar', 'Dramatik efekt'], c: 1, e: 'Van Gogh\'un sarmal fırça darbeleri; gökyüzündeki enerji ve hareket hissini görsel olarak aktarır. Bu tablo 1889\'da Saint-Paul-de-Mausole akıl hastanesinde yatarken yapıldı.', d: 2 },
  { q: '"Rembrandt" hangi teknikle öne çıkmıştır?', a: ['Nokta baskı', 'Işık-gölge (chiaroscuro) ustası; bakır baskı ve yağlı boyada dramatik ışık oyunları', 'Fresk', 'Mozaik'], c: 1, e: 'Rembrandt van Rijn, 17. yüzyıl Hollanda\'sının en büyük ustasıdır; özellikle karanlık arka plandan parlayan dramatik ışık kullanımıyla tanınır.', d: 2 },
  { q: '"Mona Lisa"nın "gizemli gülümsemesi" neden tartışmalıdır?', a: ['Yalnızca teknik mükemmeliyetten', 'Subtonal ışık geçişleri ve sfumato tekniğinin yarattığı belirsizlik; bakış açısına göre değişen ifade', 'Boyaların solması', 'Modelin kim olduğu bilinmediğinden'], c: 1, e: 'Da Vinci\'nin sfumato tekniği; gülümsemenin kenarlarını bulanıklaştırarak izleyicinin bakış açısına ve göz hareketine bağlı değişen bir ifade illüzyonu yaratır.', d: 3 },
  { q: '"Salvador Dalí"nin en ünlü tablosunun adı nedir?', a: ['Guernica', 'The Persistence of Memory (Belleğin Azmi)', 'Les Demoiselles d\'Avignon', 'The Scream'], c: 1, e: 'Salvador Dalí\'nin 1931 tarihli "The Persistence of Memory" (Belleğin Azmi) tablosu; eriyen saatlerle zamanın akışkanlığını simgeleyen Sürrealizm\'in ikonik eseridir.', d: 1 },
  { q: '"Edward Munch"un "Çığlık" (The Scream) eserinde ne betimlenmiştir?', a: ['Deniz fırtınası', 'Varoluşsal kaygı ve paniği ifade eden figür; eriyen manzara', 'Bir savaş sahnesi', 'Dini tablo'], c: 1, e: 'Munch\'un 1893 tarihli Çığlık\'ı; doğanın "sonsuz bir çığlık attığı" hissini yaşayan kaygı dolu bir figürü, çarpık fırça darbeleriyle boyanmış eriyen bir manzara önünde gösterir.', d: 1 },
  { q: '"Henri Matisse" hangi sanat akımıyla özdeşleşir?', a: ['Kübizm', 'Empresyonizm', 'Fovizm', 'Ekspresyonizm'], c: 2, e: 'Henri Matisse; parlak, cesur renkleri ve basitleştirilmiş formlarıyla tanınan Fovizm\'in (Les Fauves - "Vahşi Hayvanlar") öncüsüdür.', d: 2 },
  { q: '"Jackson Pollock"un "action painting" tekniği nedir?', a: ['Küçük fırça darbeleriyle detaylı çalışma', 'Tuvale damlatan, döküp sıçratan beden hareketleriyle boya uygulama', 'Soyut geometrik şekiller', 'Fotoğrafçılık'], c: 1, e: 'Pollock; tuvali yere yayıp etrafında dolaşarak boya dökerek ve sıçratarak çalışırdı. Bu süreç odaklı beden hareketi sanat eserinin kendisi haline getirdi.', d: 2 },
  { q: '"Mark Rothko"nun tabloları ne anlama gelir?', a: ['Somut nesneler', 'Renk alanları; izleyicide derin duygusal deneyim yaratmaya yönelik büyük renkli dikdörtgenler', 'Soyut figürler', 'Manzara resimleri'], c: 1, e: 'Rothko\'nun büyük boyutlu renk alanları; dikkatli bir izleyicide hüzün, neşe ya da mistik bir deneyim yaratmayı hedefler. Sanatçı tablolarının ağlatması gerektiğini söylemiştir.', d: 2 },
  { q: '"Turner"ın deniz resimleri neden önemlidir?', a: ['Yalnızca tarihsel değeri', 'Işık, atmosfer ve hareketi soyutlamaya yakın bir dille aktararak Empresyonizm\'i önceden haber verdi', 'İlk deniz resimleri olduğu için', 'Sadece İngiltere\'de değer gördü'], c: 1, e: 'J.M.W. Turner\'ın 19. yüzyıl deniz ve manzara resimleri; geleneksel çizgisel anlatıdan uzaklaşarak atmosferi ve ışığı öne çıkarmasıyla Fransız Empresyonizmi\'nin habercisi sayılır.', d: 3 },
  { q: '"Michelangelo" heykeli nasıl tanımlar?', a: ['Maddenin dönüşümü', '"Mermer içinde zaten var olan figürü açığa çıkarmak"', 'Şekil yaratmak', 'Modeli kopyalamak'], c: 1, e: 'Michelangelo\'nun heykeli; mermerin içinde halihazırda var olan formu ortaya çıkarmak olarak tanımlaması sanat tarihi mitolojisine girmiştir.', d: 2 },
  { q: '"Donatello"nun "Davud" heykeli neden önemlidir?', a: ['İlk mermer heykel', 'İtalyan Rönesansı\'nda tam boy çıplak insan figürünün ilk büyük bronz örneği', 'İlk dini heykel', 'En büyük heykel'], c: 1, e: 'Donatello\'nun bronz Davud\'u (1440\'lar), Rönesans\'ta tam boy çıplak bronz figürün erken dönem başyapıtı sayılır ve klasik Yunan etkisini anımsatır.', d: 3 },
  { q: '"Bernini"nin "Santa Teresa\'nın Vecdi" heykeli hangi döneme aittir?', a: ['Rönesans', 'Barok', 'Rokoko', 'Gotik'], c: 1, e: 'Gian Lorenzo Bernini\'nin 1647-52 tarihli bu heykeli; Barok dönemin dramatik hareket, ışık oyunu ve duygusal yoğunluğunu taştaki zirveye taşıyan başyapıttır.', d: 2 },
  { q: '"Türk nakış sanatı"nın geleneksel renk ve motifleri nelerdir?', a: ['Yalnızca siyah beyaz', 'Kırmızı, mavi, altın sarısı; çiçek, lale, karanfil motifleri', 'Yalnızca geometrik', 'Yalnızca yeşil'], c: 1, e: 'Türk nakış geleneği; kırmızı, mavi, altın gibi canlı renkler ve özellikle lale, karanfil, gül, nar gibi bitkisel motiflerle bezeli zengin bir estetik sunar.', d: 2 },
  { q: '"Tezhip sanatı" ne anlama gelir?', a: ['Cam boyama', 'El yazmaları ve kitaplarda altın yaldızla uygulanan geleneksel süsleme sanatı', 'Taş oymacılığı', 'Kumaş dokuma'], c: 1, e: 'Tezhip; el yazmalarının, Kuran nüshalarının ve belgelerin kenar ve sayfa boşluklarına altın yaldız ve renkli pigmentlerle uygulanan İslam dünyasının geleneksel kitap süsleme sanatıdır.', d: 2 },
  { q: '"Türk kilim" ile "Türk halı" arasındaki temel fark nedir?', a: ['İkisi aynıdır', 'Kilim düz dokuma (havasz); halı ilmekli dokuma (havlı) yapılır', 'Halı daha büyüktür', 'Kilim daha pahalıdır'], c: 1, e: 'Kilim; ilmek kullanılmadan düz dokuma yöntemiyle üretilir. Halı ise ilmek tekniğiyle havlı dokuma yapılır; bu iki yöntem farklı doku ve görünüm yaratır.', d: 2 },
  { q: '"Karagöz ve Hacivat" gölge oyununun temel malzemesi nedir?', a: ['Ahşap kuklalar', 'Deriden yapılmış şeffaf veya renklendirilmiş figürler ve ışıklı ekran', 'Kumaş kuklalar', 'Cam malzeme'], c: 1, e: 'Karagöz ve Hacivat figürleri; genellikle deve ya da manda derisinden işlenerek hazırlanan, ışıklı beyaz ekranda gölge oluşturan renkli dekoratif figurlerden yapılır.', d: 2 },
  { q: '"Türk el sanatlarında" "sırma" ne anlama gelir?', a: ['İpek kumaş', 'Altın ya da gümüş tel kullanılarak yapılan süsleme işlemeciliği', 'Taş nakışı', 'Deri boyama'], c: 1, e: 'Sırma; metal tel (altın, gümüş) ile kumaş üzerine yapılan işleme sanatıdır. Osmanlı saray kıyafetleri ve askeri giysilerde yoğun kullanılmıştır.', d: 2 },
  { q: '"Iznik çinisinin" üretimi hangi dönemde zirveye ulaştı?', a: ['Selçuklu dönemi', 'Osmanlı dönemi 15-17. yüzyıllar', '19. yüzyıl', 'Cumhuriyet dönemi'], c: 1, e: 'İznik çinisi, 15. yüzyıldan 17. yüzyıla kadar süren Osmanlı altın çağında kobalt mavisi, kırmızı ve beyazla hazırlanan muhteşem özgün kompozisyonlarla zirveye ulaştı.', d: 2 },
  { q: '"Türkiye\'de modern sanat müzesi" olarak öne çıkan kurum hangisidir?', a: ['Topkapı Sarayı Müzesi', 'Istanbul Modern', 'Ankara Etnografya Müzesi', 'Pera Müzesi'], c: 1, e: 'İstanbul Modern (2004), Türkiye\'nin ilk modern ve çağdaş sanat müzesidir; güncel Türk sanatını ve uluslararası sergileri bünyesinde barındırır.', d: 2 },
  { q: '"Pera Müzesi"nin önemi nedir?', a: ['Yalnızca Osmanlı eserleri', 'Osman Hamdi Bey\'in eserleri ve özel koleksiyonları barındıran İstanbul\'daki sanat müzesi', 'Yalnızca modern sanat', 'Devlet müzesi'], c: 1, e: 'Pera Müzesi, Suna ve İnan Kıraç Vakfı\'nın özel koleksiyonunu barındırır; Osman Hamdi Bey\'in tabloları başta olmak üzere Osmanlı resim sanatı ve Anadolu ağırlıklı eserleriyle öne çıkar.', d: 2 },
  { q: '"Türk edebiyatında Nobel Ödülü" kazanan eser hangisidir?', a: ['Mesnevi', 'Orhan Pamuk\'un "Benim Adım Kırmızı" başta olmak üzere yapıtları', 'Yaşar Kemal\'in eserleri', 'İnce Memed'], c: 1, e: 'Orhan Pamuk, 2006 Nobel Edebiyat Ödülü\'nü kazandı; "Benim Adım Kırmızı" ve "Kar" gibi eserleri uluslararası beğeni topladı.', d: 1 },
  { q: '"Nazım Hikmet" Türk edebiyatında nasıl bir yere sahiptir?', a: ['Divan şairi', 'Serbest Türkçe şiirin öncüsü ve toplumcu şiirin en önemli temsilcisi', 'Roman yazarı', 'Tiyatro yazarı'], c: 1, e: 'Nazım Hikmet Ran; serbest şiir formunu Türk edebiyatına taşıyan, toplumsal temaları lirik dille buluşturan ve pek çok dile çevrilen Türk şiirinin dünya çapında tanınan ustasıdır.', d: 1 },
  { q: '"Yaşar Kemal" hangi eserleriyle tanınır?', a: ['Mesnevi', 'İnce Memed ve Çukurova efsaneleri', 'Yalnızca şiir', 'Divan edebiyatı'], c: 1, e: 'Yaşar Kemal; İnce Memed, Dağın Öte Yüzü gibi epik romanlarıyla Anadolu halk geleneğini ve Çukurova coğrafyasını evrensel bir dille dünya edebiyatına taşıdı.', d: 1 },
  { q: '"Türk müziğinde makam" ne anlama gelir?', a: ['Ritim kalıbı', 'Belirli perde dizisi ve melodik kurallara sahip müzik modu', 'Enstrüman türü', 'Nota sistemi'], c: 1, e: 'Makam; Türk müziğinde belirli perdeler, seyir kuralları ve karakteristik melodic formüllerden oluşan modal müzik çerçevesidir. Hicaz, Rast, Uşşak gibi yüzlerce makam mevcuttur.', d: 2 },
  { q: '"Fasıl müziği" nedir?', a: ['Türk halk müziği', 'Türk sanat müziğinin eserlerden oluşan toplu icra geleneği', 'Dini müzik', 'Askeri müzik'], c: 1, e: 'Fasıl; Türk sanat müziğinde aynı makamdan seçilmiş peşrev, şarkı, saz semaisi gibi farklı formların art arda seslendirilerek oluşturduğu toplu icra geleneğidir.', d: 2 },
  { q: '"Münir Nurettin Selçuk" Türk müziğinde kim olarak tanınır?', a: ['Besteci', 'Türk sanat müziğinin efsanevi yorumcusu', 'Halk ozanı', 'Caz müzisyeni'], c: 1, e: 'Münir Nurettin Selçuk (1900-1981), Türk sanat müziğinin ses tekniğini ve sahneleme anlayışını dönüştüren, onlarca eseri klasikleştiren usta yorumcusudur.', d: 2 },
  { q: '"Zeki Müren" Türk müziğinde nasıl anılır?', a: ['Halk ozanı', '"Sanat Güneşi" lakabıyla Türk sanat müziğinin efsanesi', 'Caz sanatçısı', 'Arabesk şarkıcısı'], c: 1, e: 'Zeki Müren; müzik, tiyatro ve sinema yeteneğini, çarpıcı sahne kıyafetleri ve yorumuyla birleştirerek "Sanat Güneşi" lakabını kazanan çok boyutlu bir Türk sanat ustasıdır.', d: 1 },
  { q: '"Barış Manço" Türk müziğinde hangi özgün tarzla tanınır?', a: ['Yalnızca pop', 'Türk halk müziğini rock ile harmanlayan özgün sentez', 'Yalnızca arabesk', 'Klasik Türk müziği'], c: 1, e: 'Barış Manço; Türk halk müziği enstrümanlarını elektro gitar ile buluşturan, özgün kostümleri ve "Dönence" gibi hitleriyle milyonları büyüleyen ikonik Türk müzisyenidir.', d: 1 },
  { q: '"Sezen Aksu" Türk pop müziğine nasıl katkıda bulunmuştur?', a: ['Yalnızca şarkıcı', 'Söz yazarı, besteci ve yorumcusu olarak Türk pop müziğini şekillendiren "Türk Popunun Kraliçesi"', 'Yalnızca dini müzik', 'Yalnızca folk'], c: 1, e: 'Sezen Aksu; söz yazarlığı, besteciliği ve sesini bir arada kullanan, Tarkan ve diğer pek çok sanatçıya şarkılar yazan ve "küçük hanım" lakabıyla sevilen Türk pop müziğinin efsanevi ismidir.', d: 1 },
  { q: '"Arabesk müzik" nedir?', a: ['Tamamen Arap müziği', 'Türkiye\'ye özgü, Arap etkisi ve Türk melodileriyle halk müziğinin harmanından doğan duygusal müzik türü', 'Klasik Türk müziği türü', 'Orkestra müziği'], c: 1, e: 'Arabesk; Türkiye\'de özellikle göç edenlerin kentlerde yarattığı, Arap müziği etkisi taşıyan, hüzün ve kader temalarını öne çıkaran özgün müzik türüdür. Orhan Gencebay bu türün kurucusu sayılır.', d: 1 },
  { q: '"Türkiye\'de opera" hangi kurumla yaygınlaştı?', a: ['TRT', 'Devlet Opera ve Balesi (DOB)', 'Özel opera şirketleri', 'İstanbul Müzik Festivali'], c: 1, e: 'Devlet Opera ve Balesi (DOB), kuruluşundan bu yana Ankara, İstanbul ve diğer büyük şehirlerde Türk opera ve bale sanatını halka ulaştıran ana kamu kurumudur.', d: 2 },
  { q: '"Türkiye\'de çağdaş sanat" alanında öne çıkan etkinlik nedir?', a: ['Yalnızca müze sergileri', 'İstanbul Bienali ve çeşitli çağdaş sanat fuarları', 'Yalnızca okul etkinlikleri', 'Yalnızca devlet sergileri'], c: 1, e: '1987\'den bu yana iki yılda bir düzenlenen İstanbul Bienali; Türkiye\'nin en prestijli çağdaş sanat etkinliği ve uluslararası sanat çevrelerinin buluşma noktasıdır.', d: 2 },
  { q: '"Heykel sanatında "çok malzeme" (mixed media) ne anlama gelir?', a: ['Sadece mermer', 'Birden fazla farklı malzeme ya da tekniğin bir arada kullanıldığı sanat', 'Boyamanın bir türü', 'Sadece metal'], c: 1, e: 'Mixed media (karışık teknik); video, fotoğraf, tekstil, metal ve boyayı bir arada kullanarak geleneksel malzeme sınırlarını aşan çağdaş sanat pratiğidir.', d: 2 },
  { q: '"Duchamp"ın "Çeşme" (Fountain) eseri sanat tarihini nasıl etkiledi?', a: ['Teknique açısından öncü', 'Sıradan bir pisuarın "sanat" olarak sunulmasıyla "hazır nesne" (readymade) kavramını yarattı', 'İlk soyut heykel', 'Dini sanat eleştirisi'], c: 1, e: 'Marcel Duchamp, 1917\'de imzalayıp sergiye sunduğu pisuarla sanatın ne olduğu sorusunu kökten sorguladı; "readymade" kavramı ve Dada hareketi üzerindeki etkisi günümüz sanatını şekillendirmeye devam etmektedir.', d: 2 },
  { q: '"Joseph Beuys"un "performans sanatı" anlayışı nedir?', a: ['Geleneksel sahne sanatı', 'Her insanın sanatçı olduğu ve sanatın toplumu iyileştirme işlevi gördüğü genişletilmiş sanat anlayışı', 'Yalnızca dans', 'Resim sanatı'], c: 1, e: 'Joseph Beuys; "Her insan bir sanatçıdır" sözü ve toplumsal eleştirilerini beden performansına dönüştüren eylemleriyle 20. yüzyılın en etkili kavramsal sanatçılarından biridir.', d: 3 },
  { q: '"Türkiye\'de müzik eğitimi"nin temel kurumu nedir?', a: ['TRT Orkestrası', 'Konservatuvar (Devlet ve üniversite bağlantılı)', 'Yalnızca özel okullar', 'Milli Eğitim Bakanlığı'], c: 1, e: 'Türkiye\'deki devlet konservatuvarları ve üniversite konservatuvarları; klasik müzik, Türk müziği ve sahne sanatları eğitiminin temel kurumlarıdır.', d: 2 },
  { q: '"Gustav Klimt"in sanatının ayırt edici özelliği nedir?', a: ['Siyah beyaz', 'Altın yaldız kullanımı ve dekoratif sembolizm; Art Nouveau ve Sembolizm\'in sentezi', 'Minimalizm', 'Soyut boya damlaları'], c: 1, e: 'Klimt\'in "Öpücük" ve "Judith" gibi eserleri; Bizans mozaiğinden ilham alan altın yaldız uygulaması, bedenin dekoratif motiflerle iç içe geçmesi ve sembolik yorumlarla Art Nouveau\'nun zirvesini oluşturur.', d: 2 },
  { q: '"Egon Schiele" sanat tarihinde nasıl anılır?', a: ['Empresyonist ressam', 'İnsan bedenini çarpıtılmış, gergin ve savunmasız biçimde aktaran Ekspresyonist Avusturyalı ressam', 'Soyut sanatçı', 'Heykeltıraş'], c: 1, e: 'Egon Schiele; Klimt\'in öğrencisi olup insan figürünü çarpıtılmış, sert çizgilerle betimleyen ve cinselliği ya da ölümlülüğü psikolojik yoğunlukla ele alan Avusturyalı Ekspresyonisttir.', d: 3 },
  { q: '"Toulouse-Lautrec"in sanatının özelliği nedir?', a: ['Dini tablolar', '19. yüzyıl sonu Paris gece hayatını; kabaret, dans salonları ve sanatçıları belgeleyen afişler ve litografiler', 'Manzara resimleri', 'Portreler'], c: 1, e: 'Lautrec\'in Moulin Rouge afişleri ve litografileri; 1880-90\'lar Montmartre\'ı, dans ve gece hayatını canlı çizgi ve renk tasarımıyla ölümsüzleştirdi; modern grafik tasarımı etkiledi.', d: 2 },
  { q: '"Banksy" kim/nedir?', a: ['Ünlü Fransız ressam', 'Kimliği bilinmeyen İngiliz sokak sanatçısı; siyasi hiciv içeren grafiti ve enstalasyonlarıyla tanınır', 'Bir sanat müzesi', 'Çizgi film karakteri'], c: 1, e: 'Banksy, kimliği gizemini koruyan İngiliz sokak sanatçısıdır; şiddet karşıtlığı, tüketicilik eleştirisi ve siyasi hicivi grafiti ve enstalasyona dönüştürerek dünya gündemine girdi.', d: 1 },
  { q: '"Yayoi Kusama"nın sanatının ayırt edici unsuru nedir?', a: ['Karanlık renkler', 'Puanlar ve tekrarlayan örüntüler; sonsuzluk odaları ve soyut enstalasyonlar', 'Geleneksel Japon resim', 'Heykel'], c: 1, e: 'Yayoi Kusama; onlarca yıl boyunca puan obsesyonunu tüm yüzeylere, kendiğine ve sonradan devasa enstalasyonlara uyguladı; "Sonsuzluk Odaları" serisi dünya çapında büyük ilgi gördü.', d: 2 },
  { q: '"Ai Weiwei" kim olarak tanınır?', a: ['Japon geleneksel sanatçı', 'Çinli çağdaş sanatçı ve aktivist; siyasi eleştirilerini sanatıyla bütünleştiriyor', 'Amerikan heykeltıraşı', 'Fransız mimar'], c: 1, e: 'Ai Weiwei; Çin hükümetini eleştiren enstalasyonları, insan hakları savunuculuğu ve mimarisiyle dünyanın en tanınan çağdaş sanatçı-aktivistlerinden biridir.', d: 2 },
  { q: '"Cindy Sherman"in fotoğrafları neyle öne çıkar?', a: ['Doğa fotoğrafçılığı', 'Farklı kadın arketiplerini canlandırdığı öz portreleriyle kimlik, medya ve toplumsal cinsiyet sorgulaması', 'Manzara çekimleri', 'Belgesel fotoğrafçılık'], c: 1, e: 'Cindy Sherman; kılık değiştirerek çeşitli kadın arketiplerini ve medya klişelerini kendisi canlandırdığı fotoğraf serisiyle kimlik, cinsiyet ve temsil üzerine derin sorular sorar.', d: 3 },
  { q: '"Wolfgang Amadeus Mozart" kaç yaşında hayatını kaybetti?', a: ['25', '30', '35', '41'], c: 2, e: 'Wolfgang Amadeus Mozart, 35 yaşında 5 Aralık 1791\'de Viyana\'da hayatını kaybetti; kısa ömrüne yüzlerce eser sığdırdı.', d: 1 },
  { q: '"Ludwig van Beethoven" hangi zorlukla mücadele etmiştir?', a: ['Görme engeli', 'İşitme kaybı; sonunda tamamen sağır oldu', 'Fiziksel engel', 'Ruh sağlığı sorunu'], c: 1, e: 'Beethoven, 20\'li yaşlarında başlayan işitme kaybıyla mücadele etti ve kariyerinin son döneminde tamamen sağır olmasına rağmen 9. Senfoni dahil başyapıtlarını besteledi.', d: 1 },
  { q: '"Johann Sebastian Bach" hangi dönem ve tarzla özdeşleşir?', a: ['Klasik dönem', 'Barok dönem; kontrpuan ve polifoninin ustası', 'Romantik dönem', 'Empresyonist dönem'], c: 1, e: 'Bach, 1600-1750 Barok döneminin zirvesidir; Mathew Passion, Das Wohltemperierte Klavier ve Brandenburg Konçertoları gibi yapıtlarla kontrpuan sanatını zirveye taşıdı.', d: 2 },
  { q: '"Frédéric Chopin"in müziği hangi enstrümanla özdeşleşir?', a: ['Keman', 'Piyano', 'Çello', 'Klarnet'], c: 1, e: 'Chopin neredeyse tüm eserlerini piyano için yazdı; etüdleri, noktürnleri ve polonezleriyle Romantik dönem piyano edebiyatının en önemli bestecisidir.', d: 1 },
  { q: '"Igor Stravinsky" hangi balenin müziğini yazmıştır?', a: ['Kuğu Gölü', 'Uyuyan Güzel', 'Ateş Kuşu, Bahar Ayini, Mahraba', 'Don Kişot'], c: 2, e: 'Stravinsky; Ateş Kuşu (1910), Mahraba (1911) ve Bahar Ayini (1913) ile çağdaş müziğin seyrini değiştirdi; Bahar Ayini\'nin prömiyeri skandala yol açtı.', d: 2 },
  { q: '"Billie Holiday" kimdir?', a: ['Klasik viyolinist', 'Amerikan caz ve blues şarkıcısı; "Strange Fruit" ile ırkçılığı sanat diliyle eleştirdi', 'Türk pop sanatçısı', 'Fransız opera şarkıcısı'], c: 1, e: 'Billie Holiday; caz tarihinin en etkili seslerinden biri olan ve "Strange Fruit" şarkısıyla ABD\'deki ırkçı linç pratiğini dünya gündemine taşıyan Afro-Amerikan blues-caz sanatçısıdır.', d: 2 },
  { q: '"Miles Davis" modern caza ne kazandırdı?', a: ['Yalnızca trompet tekniği', '"Sessizliğin gücü" ve cool jazz, modal jazz, fusion gibi yeni caz stillerinin öncülüğü', 'Blues armonisi', 'Klasik form'], c: 1, e: 'Miles Davis; Kind of Blue, Bitches Brew gibi albümlerle sürekli kendini yeniledi; cool jazz, modal jazz ve jazz-rock füzyonunu şekillendirerek 20. yüzyılın en etkili müzisyenlerinden biri oldu.', d: 2 },
  { q: '"The Beatles" müzik tarihini nasıl değiştirdi?', a: ['Yalnızca İngiltere\'de etki yarattı', 'Rock\'n\'roll\'u sanatsal biçimde geliştirerek stüdyo çalışması, söz yazarlığı ve pop kültürünü dönüştürdü', 'Yalnızca 1 albüm çıkardı', 'Yalnızca caz müziği yaptı'], c: 1, e: 'The Beatles; 1960\'larda söz yazarlığı, armoni, stüdyo yenilikleri (Sgt. Pepper) ve kültürel etkileriyle rock müziğini sanatsal bir disipline dönüştürerek tüm dünyayı sardı.', d: 1 },
  { q: '"Arabesk müziğin babası" olarak anılan sanatçı kimdir?', a: ['Müslüm Gürses', 'Orhan Gencebay', 'İbrahim Tatlıses', 'Bülent Ersoy'], c: 1, e: 'Orhan Gencebay; 1969\'da "Bir Teselli Ver" ile başlayan müzik yolculuğuyla Türkiye\'de arabesk türünü oluşturan ve bu türün kurucusu olarak anılan isimdir.', d: 1 },
  { q: '"Müslüm Gürses" neden efsane sayılır?', a: ['En fazla albüm satan', 'Dramatik yorumu ve sözleriyle arabesk müzikte derin iz bırakan "Müslüm Baba"', 'Yalnızca filmlerde oynayan', 'Klasik müzik yorumcusu'], c: 1, e: 'Müslüm Gürses; acı, aşk ve kaderi derin bir coşkuyla yorumlayan sesi ve "Müslüm Baba" kimliğiyle Türkiye\'nin en sevilen arabesk sanatçılarından biri olarak tarihe geçti.', d: 1 },
  { q: '"Türk rock müziğinin" öncüsü sayılan grup kimdir?', a: ['Sezen Aksu', 'Moğollar ve Cem Karaca', 'Tarkan', 'Sertab Erener'], c: 1, e: 'Moğollar ve Cem Karaca; Türk halk müziğini rock ile birleştirerek "Anadolu rock" anlayışını 1960-70\'lerde oluşturan öncü isimlerdir.', d: 2 },
  { q: '"Tarkan" Türk pop müziğinde nasıl öne çıkmıştır?', a: ['Yalnızca Türk dinleyiciler için', 'Uluslararası arenada da iz bırakan sahne performansı ve müziğiyle "Mega Star" unvanını kazandı', 'Yalnızca arabesk', 'Yalnızca 1 albüm çıkardı'], c: 1, e: 'Tarkan; Hepsi Senin Mi, Şımarık gibi hitleriyle uluslararası arenada da tanınan, güçlü sahne performansı ve kalabalık dinleyici kitlesiyle Türk pop tarihinin en büyük isimlerinden biridir.', d: 1 },
  { q: '"Türkiye\'de sanat eğitimi" hangi kurumlar aracılığıyla verilmektedir?', a: ['Yalnızca özel atölyeler', 'Güzel sanatlar fakülteleri, konservatuvarlar, mesleki liseler ve özel sanat okulları', 'Yalnızca devlet müzeleri', 'Yalnızca yurt dışı bursları'], c: 1, e: 'Türkiye\'de sanat eğitimi; güzel sanatlar ve tasarım fakülteleri, devlet konservatuvarları, güzel sanatlar liseleri ve özel sanat okulları aracılığıyla çeşitli kademelerde verilmektedir.', d: 2 },
  { q: '"Gotik" mimari hangi yapıyla simgeleşmiştir?', a: ['Partenon', 'Notre-Dame Katedrali', 'Pantheon', 'Hagia Sophia'], c: 1, e: 'Notre-Dame de Paris, sivri kemerleri, uçan payandaları ve renkli vitraylarıyla Gotik mimari geleneğinin en tanınan simgelerinden biridir.', d: 1 },
  { q: '"Bauhaus" tasarım okulu hangi ülkede kuruldu?', a: ['İsviçre', 'Avusturya', 'Almanya', 'İsveç'], c: 2, e: 'Bauhaus; 1919\'da Walter Gropius\'un önderliğinde Almanya\'nın Weimar şehrinde kurulan ve sanat-zanaat-endüstri birlikteliğini savunan devrimci tasarım okuludur.', d: 2 },
  { q: '"Empresyonizm" neden akademiye karşı çıktı?', a: ['Figür resmine karşı', 'Akademik kurallar yerine anlık izlenim ve ışık-renk deneyimini öne çıkardı', 'Renkten kaçındı', 'Yalnızca portre yaptı'], c: 1, e: 'Empresyonistler; Fransız Akademisi\'nin sert çizgi ve "yüksek konu" anlayışını reddederek gündelik yaşamı, doğayı ve anlık ışık değişimini tuvale aktarmayı tercih etti.', d: 2 },
  { q: '"Duchamp"ın dışında "ready-made" (hazır nesne) kavramını kullanan diğer önemli sanatçılar kimlerdir?', a: ['Yalnızca Duchamp', 'Andy Warhol, Jeff Koons ve Damien Hirst gibi sanatçılar hazır nesneyi farklı biçimlerde kullandı', 'Yalnızca Picasso', 'Yalnızca Kandinsky'], c: 1, e: 'Andy Warhol\'un Campbell\'s çorba kutuları, Jeff Koons\'un balon köpekleri ve Damien Hirst\'in formaldehit içindeki hayvanları; ready-made kavramını çeşitli biçimlerde yorumlayan önemli örneklerdir.', d: 2 },
  { q: '"Minyatür resim" Türk-İslam sanatında hangi malzeme üzerine yapılırdı?', a: ['Tuval', 'El yazması kağıt, deri ve fildişi üzerine', 'Ahşap', 'Taş'], c: 1, e: 'Geleneksel minyatür resmi; el yazması kitapların kağıt sayfaları, deri ya da fildişi üzerine doğal pigmentlerle hazırlanan çok ince fırçayla yapılırdı.', d: 2 },
  { q: '"Türk hat sanatının" en önemli ustası kimdir?', a: ['Sinan', 'Şeyh Hamdullah', 'Osman Hamdi Bey', 'İbrahim Çallı'], c: 1, e: 'Şeyh Hamdullah (1436-1520), Osmanlı hat sanatının en büyük ustası kabul edilir; geliştirdiği üslup bugün hâlâ hat sanatının referans noktasıdır.', d: 2 },
  { q: '"Türk sedefkârlığı" nedir?', a: ['Ahşap boyama', 'Sedef kabuğu parçalarının ahşap eşya üzerine kakılmasıyla yapılan geleneksel süsleme sanatı', 'Cam işlemeciliği', 'Kumaş dokuma'], c: 1, e: 'Sedefkârlık; inci sedefinin ince dilimlerinin ahşap yüzeylere kakılması ve perdahlanmasıyla elde edilen Osmanlı-Türk el sanatıdır. Özellikle sandık, müzik aleti ve mobilyalarda kullanılır.', d: 2 },
  { q: '"Türk çini ve seramiğinin" dünya müzelerindeki önemi nedir?', a: ['Yalnızca Türkiye\'de ilgi görür', 'Louvre, British Museum ve Metropolitan müzelerinde Osmanlı dönemi çini koleksiyonları sergilenmektedir', 'Yalnızca İznik\'te üretilir', 'Modern sanat sayılır'], c: 1, e: 'Osmanlı dönemine ait İznik çinileri ve seramikleri; Paris Louvre, Londra British Museum ve New York Metropolitan müzelerinde önemli koleksiyonlarla sergilenmektedir.', d: 2 },
  { q: '"Tanzimat dönemi edebiyatı"nın öne çıkan özellikleri nelerdir?', a: ['Yalnızca divan şiiri', 'Divan geleneğinden Batılı biçimlere geçiş; roman, tiyatro ve gazete edebiyatının başlangıcı', 'Yalnızca halk edebiyatı', 'Yalnızca dini edebiyat'], c: 1, e: 'Tanzimat edebiyatı; Namık Kemal, Şinasi ve Ahmet Cevdet Paşa gibi yazarların roman, tiyatro ve gazete türleriyle Divan geleneğinden Batılı anlatı biçimlerine geçişi sağladığı devrimsel dönemdir.', d: 2 },
  { q: '"Servet-i Fünun" edebiyat akımı nedir?', a: ['Halk şiiri', 'Batı estetiğini Osmanlı Türkçesiyle buluşturan 1890\'lar edebiyat topluluğu', 'Dini edebiyat', 'Cumhuriyet dönemi'], c: 1, e: 'Servet-i Fünun; 1890\'larda Recaizade Mahmut Ekrem ve Tevfik Fikret önderliğinde Fransız Parnasyen-Sembolizm etkisiyle şekillenen, aynı adlı dergide toplanan edebi topluluktur.', d: 3 },
  { q: '"Milli Edebiyat" hareketi Türk edebiyatında ne anlama gelir?', a: ['Osmanlı divan şiiri', 'Sade Türkçe ve halk kaynaklarına yönelen 20. yüzyıl başı milliyetçi edebiyat akımı', 'Batı taklitçiliği', 'Dini edebiyat'], c: 1, e: 'Milli Edebiyat; Ömer Seyfettin, Ziya Gökalp ve Halide Edib gibi isimlerin önderliğinde sade Türkçeyi, halk kültürünü ve milli kimliği ön plana çıkaran 1910\'lu yılların edebiyat hareketidir.', d: 2 },
  { q: '"Cumhuriyet dönemi Türk resmi"nin öne çıkan temsilcisi kimdir?', a: ['Osman Hamdi Bey', 'İbrahim Çallı', 'Namık İsmail', 'Hepsi birden farklı dönemlerde'], c: 3, e: 'Türk resminin kuşakları farklıdır: Osman Hamdi Bey (Osmanlı son dönemi), İbrahim Çallı ve Namık İsmail (Çallı kuşağı, Cumhuriyet erken dönemi); her biri kendi döneminin öncüsüdür.', d: 2 },
  { q: '"Müzikte "doğaçlama" (improvisation) nedir?', a: ['Notadan çalmak', 'Anlık kompozisyon; sanatçının anında yaratarak icra etmesi', 'Yalnızca caz müziği', 'Şarkının tekrarı'], c: 1, e: 'Doğaçlama; sanatçının önceden yazılmış nota olmaksızın anlık ilham ve teknik beceriyle müzik üretmesidir. Caz, blues ve Türk klasik müziğinde temel icra pratiğidir.', d: 2 },
  { q: '"Rock müziği" nasıl tanımlanır?', a: ['Yalnızca gürültülü müzik', 'Elektro gitar, ritm bölümü ve güçlü vokal üzerine kurulu, 1950\'lerde doğan popüler müzik türü', 'Yalnızca Amerikan müziği', 'Yalnızca 1960\'lara özgü'], c: 1, e: 'Rock müziği; blues ve country\'den ilham alan, elektrik gitar-bas-davul üçlüsüyle şekillenen ve 1950\'lerde Elvis Presley ve Chuck Berry gibi isimlerle doğan küresel müzik türüdür.', d: 1 },
  { q: '"Hip-hop" kültürü hangi unsurlardan oluşur?', a: ['Yalnızca rap müziği', 'Rap (MC), DJ\'lik, breakdance ve grafiti olmak üzere dört temel unsur', 'Yalnızca dans', 'Yalnızca New York'], c: 1, e: 'Hip-hop kültürü; 1970\'lerde New York\'un Bronx semtinde doğan ve rap müzik, DJ\'lik (turntablism), breakdance ve grafiti sanatını kapsayan dört temel unsurdan oluşan kentsel kültür hareketidir.', d: 2 },
  { q: '"Opera"nın kökeni nerede ve ne zaman?', a: ['Almanya, 18. yüzyıl', 'İtalya, 16. yüzyıl sonu - 17. yüzyıl başı', 'Fransa, 19. yüzyıl', 'Yunanistan, antik dönem'], c: 1, e: 'Opera; 16. yüzyıl sonunda Floransa\'da Camerata adlı entelektüel grubun antik Yunan dramını müzikle canlandırma denemeleriyle doğdu. İlk opera eseri Jacopo Peri\'nin Dafne\'si (1597-98) kabul edilir.', d: 2 },
  { q: '"Bale"nin doğduğu ülke hangisidir?', a: ['Almanya', 'İtalya ve Fransa', 'Rusya', 'İspanya'], c: 1, e: 'Bale; 15-16. yüzyılda İtalyan Rönesansı\'nda saray gösterileri olarak başladı ve Fransa\'da biçimlendi. 17. yüzyılda Louis XIV döneminde profesyonel dans okulu kurulmasıyla sistematize oldu.', d: 2 },
  { q: '"Empresyonizm"de "yüzey dokusu" neden önem kazandı?', a: ['Görsel efekt için', 'Fırça izlerinin görünür bırakılması renk-ışık titreşimini artırarak anlık izlenimi güçlendirdi', 'Ekonomiklik nedeniyle', 'Gizli teknik'], c: 1, e: 'Monet ve Renoir gibi empresyonistler; düzgün yüzey yerine kalın, görünür fırça dokunuşlarıyla ışığın yüzeyde parıltısını ve anlık atmosferi yakaladılar.', d: 2 },
  { q: '"Sürrealizm" akımının öncüsü kimdir?', a: ['Salvador Dali', 'André Breton', 'Max Ernst', 'René Magritte'], c: 1, e: 'Sürrealizm; 1924\'te Fransız yazar André Breton\'un "Sürrealizm Manifestosu"yla başlatıldı. Freud\'un bilinçdışı kuramından ilham alan hareket; rüya imgelerini ve mantık dışı bağlantıları sanata taşıdı.', d: 2 },
  { q: '"Soyut dışavurumculuk" hangi ülkede doğdu?', a: ['Fransa', 'Almanya', 'ABD (New York)', 'İtalya'], c: 2, e: 'Soyut Dışavurumculuk (Abstract Expressionism); 1940\'larda New York\'ta Jackson Pollock, Mark Rothko ve Willem de Kooning gibi sanatçılarla doğdu. Sanat dünyasının ağırlık merkezini Avrupa\'dan ABD\'ye taşıdı.', d: 2 },
  { q: '"Pop Art"ı diğer akımlardan ayıran temel özellik nedir?', a: ['Soyutlama', 'Kitle kültürü, reklam, pop müzik ve tüketim nesnelerini sanat malzemesi olarak kullanmak', 'Klasik teknik', 'Heykel odaklı'], c: 1, e: 'Pop Art; Andy Warhol ve Roy Lichtenstein öncülüğünde 1950-60\'larda reklam, film yıldızları, ambalaj ve çizgi roman gibi kitle kültürü imgelerini yüksek sanata taşıdı.', d: 1 },
  { q: '"Kübizm" sanatın görsel dilini nasıl değiştirdi?', a: ['Rengi daha çok kullandı', 'Tek bakış açısı yerine çok bakış açısını aynı anda göstererek perspektif geleneğini yıktı', 'Soyutlamayı kaldırdı', 'Yalnızca heykel için gelişti'], c: 1, e: 'Picasso ve Braque\'ın geliştirdiği Kübizm; tek noktadan bakış yerine bir nesneyi farklı açılardan aynı anda parçalara bölerek resmin düzlemsel gerçekliğini öne çıkardı.', d: 2 },
  { q: '"Barok dönem" sanatının özellikleri nelerdir?', a: ['Sadelik ve soyutlama', 'Dramatik ışık-gölge, hareket, duygusallık ve görkemli süsleme; 17. yüzyıl Avrupa\'sında', 'Yalnızca mimari', 'Minimalist görüntü'], c: 1, e: 'Barok; 17. yüzyılda İtalya\'dan yayılan, Caravaggio\'nun chiaroscuro (aydınlık-karanlık) tekniği ve Bernini\'nin dramatik heykelleriyle tanınan güçlü duygusal-gösterişli sanattır.', d: 2 },
  { q: '"Rönesans sanatı"nın temel yenilikleri nelerdir?', a: ['Yalnızca dini konu', 'Perspektif (derinlik), insan anatomisi, bireysel portre ve antik Yunan-Roma mirasının yeniden canlanması', 'Soyutlama', 'Yalnızca heykel'], c: 1, e: 'Rönesans; doğrusal perspektif, insan figürünün anatomik doğruluğu, bireysel portre ve paganist antik konuların yeniden ele alınmasıyla Orta Çağ geleneğinden köklü kopuşu temsil eder.', d: 2 },
  { q: '"Michelangelo" hangi eseriyle tavan freskosunda zirveye ulaştı?', a: ['Mona Lisa', 'Son Akşam Yemeği', 'Sistine Şapeli tavanı', 'Venüs\'ün Doğuşu'], c: 2, e: 'Michelangelo; 1508-1512 yıllarında Vatikan\'daki Sistine Şapeli tavanını boyayarak dönemin en büyük sanat başarılarından birini gerçekleştirdi. Tanrı\'nın Adem\'i Yaratışı en ünlü bölümüdür.', d: 1 },
  { q: '"Fütürizm" akımı nereye ve neye odaklandı?', a: ['Geçmişi kutlamak', 'İtalya\'da doğan ve hız, makine, kentsel yaşam ve teknolojinin dinamizmini yücelten 20. yüzyıl başı akımı', 'Doğa ve huzur', 'Dini konular'], c: 1, e: 'Fütürizm; 1909\'da Marinetti\'nin manifestosuyla İtalya\'da başladı; otomobil, uçak, demir yolu ve endüstriyel dinamizmi sanatsal konu olarak benimseyerek geçmişi reddetti.', d: 2 },
  { q: '"Dadaizm" neden ortaya çıktı?', a: ['Güzelliği kutlamak için', 'Birinci Dünya Savaşı\'nın saçmalığına karşı tutumlu bir protesto hareketi olarak', 'Teknik mükemmellik için', 'Dini reform'], c: 1, e: 'Dada; 1916\'da Zürih\'te Birinci Dünya Savaşı\'nın vahşetine karşı anlamsızlığı kucaklayan bir sanat-karşıtı isyan olarak doğdu. Mantık dışı, şok edici ve ironik eserlerle kültüre meydan okudu.', d: 2 },
  { q: '"Minimalizm" sanat anlayışı neyi öngörür?', a: ['Çok renkli ve karmaşık', '"Daha azı daha çoktur"; gereksiz süsü kaldırarak saf form, renk ve materyal üzerine odaklanmak', 'Duygusal yoğunluk', 'Klasik referanslar'], c: 1, e: 'Minimalizm; 1960\'larda ABD\'de Donald Judd ve Dan Flavin gibi sanatçılarla doğdu. Gereksiz süsü reddederek formu, rengi ve malzemenin kendisini ön plana çıkardı.', d: 2 },
  { q: '"Türk ebru sanatı"nın temel tekniği nedir?', a: ['Kağıda direkt boyama', 'Su yüzeyinde kıvamlandırılmış sıvıya boyalar damlatılıp desenler oluşturulduktan sonra kağıda aktarılır', 'İpek üzerine', 'Duvar boyama'], c: 1, e: 'Ebru; kıvamlandırılmış su üzerine doğal boyalar damlatılarak oluşturulan desenlerin kağıda aktarılmasıyla yapılan Türk-İslam süsleme sanatıdır. 2014\'te UNESCO listesine alındı.', d: 1 },
  { q: '"Türk kilim sanatı" dünyada nasıl değerlendirilir?', a: ['Sıradan tekstil', 'Desenlerinin anlam ve geometrik soyutlamasıyla uluslararası müzelerde sanat eseri statüsünde', 'Yalnızca pratik kullanım', 'Yalnızca Orta Asya'], c: 1, e: 'Türk kilimleri; geometrik desenler, bölgesel renk kodları ve el dokuma geleneğiyle Smithsonian, V&A Müzesi ve Louvre gibi kurumların koleksiyonlarında yer alan uluslararası sanat eserleridir.', d: 2 },
  { q: '"Klasik müzik"te "senfoni" ile "konçerto" arasındaki fark nedir?', a: ['İkisi aynıdır', 'Senfoni orkestra için yazılır; konçerto solist ve orkestra diyaloğuna dayanır', 'Konçerto daha uzun', 'Senfoni yalnızca koral'], c: 1, e: 'Senfoni; tüm orkestra için yazılan büyük ölçekli bir yapıt. Konçerto ise bir solist (piyano, keman vb.) ile orkestranın diyalogunu öne çıkaran form. İkisi birbirinden tamamen farklı yapılardır.', d: 2 },
  { q: '"Tiyatroda "trajedi" kavramını kim sistematize etti?', a: ['Shakespeare', 'Aristoteles', 'Sophokles', 'Molière'], c: 1, e: 'Aristoteles; "Poetika" adlı eserinde trajedinin katharsis (arınma) işlevi, olayların bütünlüğü ve uygun karakter yapısını tanımladı. Günümüzde de drama kuramının temel referansı olmaya devam etmektedir.', d: 2 },
  { q: '"Anadolu\'da kilim dokuma geleneği" hangi bölgelerle özdeşleşir?', a: ['Yalnızca Ege', 'Konya, Kayseri, Sivas, Uşak ve Doğu Anadolu başta olmak üzere birçok bölge', 'Yalnızca Karadeniz', 'Yalnızca İstanbul'], c: 1, e: 'Konya, Kayseri ve Uşak gibi İç Anadolu şehirlerinin yanı sıra Doğu ve Güneydoğu Anadolu da kendine özgü desen ve renk paleti taşıyan halı-kilim geleneğiyle öne çıkar.', d: 2 },
  { q: '"Türk tasavvuf müziği"nin merkezinde ne vardır?', a: ['Yalnızca saz', 'Mevlevi semahı ve ney başta olmak üzere Tanrı\'ya yakınlaşmayı amaçlayan mistik müzik ritüeli', 'Yalnızca ilahi', 'Yalnızca davul'], c: 1, e: 'Türk tasavvuf müziği; Mevlana\'nın tekkelerinde geliştirilen ney, ud, tanbur eşliğinde ilahi ve sema ritüelini kapsar. Ney; ruhun özlemi ve Tanrı ile birliğin simgesidir.', d: 2 },
  { q: '"Heykel sanatında "bronz döküm" tekniği ne anlama gelir?', a: ['Taşa şekil vermek', 'Mum ya da alçı modelin etrafına kalıp oluşturup erimiş bronzu dökerek kalıcı heykel elde etme', 'Ahşap oyma', 'Kil şekillendirme'], c: 1, e: 'Bronz döküm; kayıp balmumu (cire perdue) tekniğiyle mum model etrafına seramik kalıp oluşturulması, mumun eritilmesi ve yerine sıvı bronzun dökülmesiyle heykel yapmayı sağlayan eski bir tekniktir.', d: 2 },
  { q: '"Türkiye\'de Güzel Sanatlar Akademisi" tarihsel önemi nedir?', a: ['Yok böyle bir kurum', 'Mekteb-i Sanayi-i Nefise (1882) olarak Osmanlı döneminde kurulan ve Batılı akademik sanat eğitimini Türkiye\'ye taşıyan okul', 'Yalnızca mimarlık okulu', 'Cumhuriyet döneminde kuruldu'], c: 1, e: 'Mekteb-i Sanayi-i Nefise; Osman Hamdi Bey\'in öncülüğünde 1882\'de İstanbul\'da açıldı. Türkiye\'nin ilk güzel sanatlar akademisi olarak Batılı sanat eğitimini Anadolu\'ya taşıdı.', d: 2 },
  { q: '"Film müziği" bir sanat dalı olarak nasıl gelişti?', a: ['Her zaman vardı', 'Sessiz sinema döneminde canlı piyano eşliğiyle başladı; sesli film döneminde orkestral kompozisyon sanatına dönüştü', 'Yalnızca modern dönemde', 'Yalnızca Hollywood'], c: 1, e: 'Film müziği; 1920\'lere kadar sessiz sinemalarda canlı piyano/org eşliğiyle sunuldu. Bernard Herrmann, Ennio Morricone ve John Williams gibi bestecilerle bağımsız bir sanat dalı haline geldi.', d: 2 },
  { q: '"Türk halk müziği" hangi enstrümanlarla özdeşleşir?', a: ['Yalnızca kemençe', 'Saz (bağlama), davul, zurna, kaval ve kemençe gibi çalgılar', 'Yalnızca davul', 'Yalnızca ud'], c: 1, e: 'Türk halk müziğinin temel çalgıları; bölgeye göre bağlama/saz, davul-zurna, kaval, mey ve Karadeniz\'e özgü kemençedir. Her bölgenin kendine özgü çalgı geleneği bulunur.', d: 1 },
  { q: '"Türk klasik müziği" hangi makamlar üzerine kurulur?', a: ['Yalnızca 7 nota', 'Rast, Uşşak, Hicaz, Segah, Nihavend gibi çok sayıda makam; Batı müziğinden farklı mikrotonal yapı', 'Yalnızca majör-minör', 'Tek makam'], c: 1, e: 'Türk klasik müziği; Batı müziğinin majör-minör sisteminden farklı olarak dörtlük ve ikinci aralıklara bölünmüş mikrotonal yapıdaki makamlar üzerine kuruludur. Her makamın kendine özgü atmosfer ve ifade kapasitesi vardır.', d: 2 },
  { q: '"Grafiti" sokak sanatı hangi ülkede ve ne zaman gelişti?', a: ['Fransa, 1950\'ler', 'ABD (New York, Philadelphia), 1960-70\'ler', 'Brezilya, 1980\'ler', 'İngiltere, 1990\'lar'], c: 1, e: 'Modern grafiti; 1960-70\'lerde New York ve Philadelphia\'da başladı. Gençler metro vagonlarına ve duvarlarına imza ve resimler yaparak sanatsal-siyasi bir dil geliştirdi. Banksy gibi isimlerle galeri ortamına taşındı.', d: 2 },
  { q: '"Heykel"de "in situ" kavramı ne anlama gelir?', a: ['Galeri sanatı', 'Eserin bulunacağı mekân gözetilerek o mekân için tasarlanmış, yerle bütünleşik eser', 'Taşınan heykel', 'Dijital heykel'], c: 1, e: 'In situ; Latince "yerinde" anlamına gelir. Sanat bağlamında; eserin belirli bir mekân için özel olarak tasarlandığı ve başka yere taşındığında özgünlüğünü yitireceği site-specific (mekâna özgü) eseri tanımlar.', d: 2 },
  { q: '"Türk geleneksel el sanatları" UNESCO\'da nasıl yer almaktadır?', a: ['Hiç kayıtlı değil', 'Ebru, Türk kahvesi geleneği, Mevlevi semahı, Karagöz ve çeşitli el sanatları UNESCO listelerinde', 'Yalnızca mimari', 'Yalnızca müzik'], c: 1, e: 'Türkiye\'nin UNESCO Somut Olmayan Kültürel Miras listelerindeki unsurlar arasında Karagöz, Mevlevi semahı, ebru, Türk kahvesi geleneği ve geleneksel Nevruz kutlamaları yer almaktadır.', d: 2 },
  { q: '"Türk tiyatrosunun" geleneksel komedi biçimi nedir?', a: ['Opera', 'Karagöz ve Hacivat ile Ortaoyunu', 'Komedi deli oya', 'Modern tiyatro'], c: 1, e: 'Karagöz ve Hacivat (gölge oyunu) ile Ortaoyunu; Türk toplumsal komedisinin geleneksel biçimleridir. Her ikisi de farklı toplum kesimlerini temsil eden karakterlerle toplumsal eleştiri içerir.', d: 1 },
  { q: '"Türk sanatında Osman Hamdi Bey"in önemi nedir?', a: ['Mimar', 'Batılı anlamda ilk profesyonel Türk ressamı; aynı zamanda arkeolog ve müzeci', 'Heykeltraş', 'Hat sanatçısı'], c: 1, e: 'Osman Hamdi Bey; 19. yüzyılda Paris\'te eğitim aldı, oryantalist eleştiri doğrultusunda önemli tuvaller üretti ve İstanbul Arkeoloji Müzesi\'ni kurdu. Türk sanat tarihinin mihenk taşlarından biridir.', d: 2 },
  { q: '"Türk hat sanatında" hangi yazı türleri kullanılır?', a: ['Yalnızca Arapça harfler', 'Sülüs, Nesih, Talik, Divani ve Rik\'a gibi çeşitli hat türleri', 'Yalnızca Türkçe', 'Yalnızca Kur\'an ayetleri'], c: 1, e: 'Hat sanatında kullanılan başlıca türler: Sülüs (kitabeler için), Nesih (Kur\'an yazımı), Talik (Farsça şiir), Divani (resmi belgeler), Rik\'a (günlük yazışma) ve Celi (büyük yazı) biçimlerini kapsar.', d: 2 },
  { q: '"Türk "meddah" sanatı" nedir?', a: ['Halk dansı', 'Tek kişilik performansla çeşitli karakterleri canlandıran Osmanlı-Türk anlatı sanatı', 'Halk müziği', 'Kukla tiyatrosu'], c: 1, e: 'Meddah; tek başına sahnede farklı sesleri ve karakterleri canlandırarak dini-ahlaki ya da komik hikayeler anlatan Türk-Osmanlı performans sanatçısıdır. UNESCO listesindedir.', d: 2 },
  { q: '"Türk çini sanatının" en parlak dönemi hangi yüzyıldır?', a: ['13. yüzyıl', '15-17. yüzyıl (Osmanlı altın çağı)', '19. yüzyıl', '20. yüzyıl'], c: 1, e: '15-17. yüzyıllar, özellikle Kanuni Sultan Süleyman dönemi; İznik ve Kütahya çiniciliğinin en yüksek kaliteye ulaştığı, kobalt mavisi ve mercan kırmızısı desenlerinin dünyanın en değerli seramikleri arasına girdiği dönemdir.', d: 2 },
  { q: '"Leonardo da Vinci\'nin" Mona Lisa\'sının gizemi nedir?', a: ['Sahtedir', 'Özgün kimliği tartışmalı; belirsiz gülümseme ve sfumato tekniği onu eşsiz kılar', 'Yarım kalmış', 'Manzara resmi'], c: 1, e: 'Mona Lisa\'nın modeli büyük olasılıkla Lisa Gherardini\'dir. Sfumato (hava perspektifi) tekniğiyle oluşturulan belirsiz gülümseme ve arka planın izleyiciye göre değişen derinliği, tabloyu tarihinin en çok incelenen eseri yapmıştır.', d: 2 },
];

export default questions;
